// The dial's typeface, carried with the code.
//
// The dials are drawn server-side now, and a serverless runtime has no system
// fonts — asking for "Arial" there gets you nothing, and the number vanishes
// from the middle of the ring with no error to say why. So the face travels
// as bytes, subset to the characters a dial can actually print.
//
// Liberation Sans, which is metric-compatible with Arial: the same shape the
// HTML around it asks for, so the picture and the text beside it agree.
// Licensed under the SIL Open Font License.

export const DIAL_FONT_BOLD = "";

export const DIAL_FONT_REGULAR = "";

